    <div class="container">
        <div class="header">
            <h1>Reserve Your Spot</h1>
            <p>Complete the form below to confirm your booking</p>
        </div>

        <div class="success-message" id="successMessage">
            ✓ Booking confirmed! We've sent a confirmation email to your address.
        </div>

        <form id="bookingForm">
            <div class="form-group">
                <label for="name">Full Name *</label>
                <input type="text" id="name" name="name" required>
                <div class="error" id="nameError">Please enter your full name</div>
            </div>

            <div class="form-group">
                <label for="email">Email Address *</label>
                <input type="email" id="email" name="email" required>
                <div class="error" id="emailError">Please enter a valid email address</div>
            </div>

            <div class="form-group">
                <label for="phone">Phone Number *</label>
                <input type="tel" id="phone" name="phone" required>
                <div class="error" id="phoneError">Please enter a valid phone number</div>
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label for="date">Date *</label>
                    <input type="date" id="date" name="date" required>
                    <div class="error" id="dateError">Please select a date</div>
                </div>

                <div class="form-group">
                    <label for="time">Time *</label>
                    <input type="time" id="time" name="time" required>
                    <div class="error" id="timeError">Please select a time</div>
                </div>
            </div>

            <div class="form-group">
                <label for="guests">Number of Guests *</label>
                <select id="guests" name="guests" required>
                    <option value="">Select number of guests</option>
                    <option value="1">1 Guest</option>
                    <option value="2">2 Guests</option>
                    <option value="3">3 Guests</option>
                    <option value="4">4 Guests</option>
                    <option value="5">5 Guests</option>
                    <option value="6+">6+ Guests</option>
                </select>
                <div class="error" id="guestsError">Please select number of guests</div>
            </div>

            <div class="form-group">
                <label for="notes">Special Requests</label>
                <textarea id="notes" name="notes" placeholder="Any dietary requirements or special requests?"></textarea>
            </div>

            <button type="submit">Confirm Booking</button>
        </form>
    </div>

    <script>
        const form = document.getElementById('bookingForm');
        const successMessage = document.getElementById('successMessage');

        form.addEventListener('submit', function(e) {
            e.preventDefault();

            // Clear all error messages
            document.querySelectorAll('.error').forEach(err => err.classList.remove('show'));

            // Validate fields
            let isValid = true;

            const name = document.getElementById('name').value.trim();
            if (!name) {
                document.getElementById('nameError').classList.add('show');
                isValid = false;
            }

            const email = document.getElementById('email').value.trim();
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(email)) {
                document.getElementById('emailError').classList.add('show');
                isValid = false;
            }

            const phone = document.getElementById('phone').value.trim();
            if (!phone) {
                document.getElementById('phoneError').classList.add('show');
                isValid = false;
            }

            const date = document.getElementById('date').value;
            if (!date) {
                document.getElementById('dateError').classList.add('show');
                isValid = false;
            }

            const time = document.getElementById('time').value;
            if (!time) {
                document.getElementById('timeError').classList.add('show');
                isValid = false;
            }

            const guests = document.getElementById('guests').value;
            if (!guests) {
                document.getElementById('guestsError').classList.add('show');
                isValid = false;
            }

            if (isValid) {
                successMessage.classList.add('show');
                form.style.display = 'none';

                setTimeout(() => {
                    console.log('Booking submitted:', {
                        name,
                        email,
                        phone,
                        date,
                        time,
                        guests,
                        notes: document.getElementById('notes').value
                    });
                }, 500);
            }
        });
    </script>
